CREATE PROCEDURE [dbo].[SP_Save_ItemBreakDowndetails]
    -- Add the parameters for the stored procedure here
    @XmLdata XML,
    @docID VARCHAR(MAX) OUTPUT,
    @Recipientheaderid INT OUTPUT
AS
DECLARE @iDocID INT;

BEGIN TRY
    BEGIN TRANSACTION;
    EXEC sp_xml_preparedocument @iDocID OUTPUT, @XmLdata;


    IF OBJECT_ID('tempdb.dbo.#JbHeader', 'U') IS NOT NULL
        DROP TABLE #JbHeader;
    IF OBJECT_ID('tempdb.dbo.#JobOutputDetails', 'U') IS NOT NULL
        DROP TABLE #JobOutputDetails;
    IF OBJECT_ID('tempdb.dbo. #JobInputDetails', 'U') IS NOT NULL
        DROP TABLE #JobInputDetails;

    SELECT ProjectID,
           PropertyID,
           BOQID,
           JobCardNumber,
           JobCreateDate,
           CreateUserID,
           CreateDate,
           Status,
           Complete,
           Approved,
           ApprovedUserID,
           ApprovedDate,
           LocationID,
           DepartmentID
    INTO #JbHeader
    FROM
        OPENXML(@iDocID, 'ItemBreakDownSave/Headers', 2) WITH dbo.JobHeaders;



    DECLARE @RequestHeaderID INT;


	


    SELECT *
    INTO #JobOutputDetails
    FROM
        OPENXML(@iDocID, 'ItemBreakDownSave/OutPutDetails/JobOutputDetails', 2)
        WITH dbo.JobOutputDetails;


    SELECT BundleStockItemHeaderId,
           DetailStockItemHeaderId,
           Quantity,
           Unit,
           Id,
           MainType
    INTO #JobInputDetails
    FROM
        OPENXML(@iDocID, 'ItemBreakDownSave/OutPutDetails/JobOutputDetails/BundleItems/BundleItems', 2)
        WITH
        (
            BundleStockItemHeaderId INT,
            DetailStockItemHeaderId INT,
            Quantity DECIMAL(18, 2),
            Unit INT,
            Id INT,
            MainType INT
        );


    --SELECT *
    --FROM #JbHeader;

    --SELECT *
    --FROM #JobOutputDetails;

    SELECT *
    FROM #JobInputDetails;
    DECLARE @DocumentNo VARCHAR(MAX);
    DECLARE @PropertyID INT,
            @LocationID INT,
            @RequestType VARCHAR(MAX) = 'JR',
            @TransactionTypeID INT;
    SELECT @PropertyID = PropertyID,
           @LocationID = LocationID
    FROM
        OPENXML(@iDocID, 'ItemBreakDownSave/Headers', 2)
        WITH
        (
            PropertyID INT,
            LocationID INT
        );


	

    SELECT @DocumentNo = dbo.FN_GetNextDocumentNumber(@PropertyID, -888, @RequestType);

    IF @DocumentNo IS NULL
    BEGIN
        INSERT INTO TransactionTypeWiseNextNumbers
        (
            PropertyID,
            LocationID,
            TransactionType,
            NextNumber,
            LengthOfFormatting
        )
        VALUES
        (@PropertyID, @LocationID, @RequestType, 1, 6);
    END;



    SELECT @DocumentNo = dbo.FN_GetNextDocumentNumber(@PropertyID, @LocationID, @RequestType);


    SELECT @DocumentNo = 'J' + @DocumentNo;

    UPDATE TransactionTypeWiseNextNumbers
    SET NextNumber = NextNumber + 1
    WHERE LocationID = @LocationID
          AND TransactionType = @RequestType;



    INSERT INTO dbo.JobHeaders
    (
        ProjectID,
        PropertyID,
        BOQID,
        JobCardNumber,
        JobCreateDate,
        CreateUserID,
        CreateDate,
        Status,
        Complete,
        Approved,
        ApprovedUserID,
        ApprovedDate,
        LocationID,
        DepartmentID
    )
    SELECT ProjectID,
           PropertyID,
           BOQID,
           @DocumentNo,
           JobCreateDate,
           CreateUserID,
           CreateDate,
           Status,
           Complete,
           Approved,
           ApprovedUserID,
           ApprovedDate,
           LocationID,
           DepartmentID
    FROM #JbHeader;

    SELECT @RequestHeaderID = SCOPE_IDENTITY();


    DECLARE @JobOutPutId INT,
            @Cal INT = 0;


    WHILE
    (SELECT COUNT(StockItemHeaderID) FROM #JobOutputDetails) > 0
    BEGIN

        SET @Cal = @Cal + 1;
        DECLARE @StockItemHeaderID INT,
                @OutputHeaderID INT,@JobQTY INT,
				@TempJobHeadId INT;

        SELECT TOP (1)
               @TempJobHeadId = JobHeaderID,@StockItemHeaderID=StockItemHeaderID,@JobQTY=QTY
        FROM #JobOutputDetails;

        INSERT INTO dbo.JobOutputDetails
        (
            JobHeaderID,
            StockItemHeaderID,
            Qty
        )
        SELECT @RequestHeaderID,
               StockItemHeaderID,
               Qty
        FROM #JobOutputDetails
        WHERE  JobHeaderID= @TempJobHeadId;

        SELECT @JobOutPutId = SCOPE_IDENTITY();


        INSERT INTO dbo.JobInputDetails
        (
            JobHeaderID,
            OutPutStockItemHeaderID,
            StockItemHeaderID,
            Qty,
            UnitID,
            RequestQty,
            IssueQty,
            JobOutPutHeadId,
            Type
        )
        SELECT @RequestHeaderID,
               @StockItemHeaderID,
               DetailStockItemHeaderId,
               Quantity*@JobQTY,
               Unit,
               0,
               0,
               @JobOutPutId,
               MainType
        FROM #JobInputDetails
        WHERE Id = @Cal;

        DELETE #JobOutputDetails
        WHERE  StockItemHeaderID= @StockItemHeaderID;

		

    END;


    SELECT @docID = @DocumentNo;







    SELECT @TransactionTypeID = Id
    FROM TransactionTypes
    WHERE Code = @RequestType;

    SELECT @Recipientheaderid = @RequestHeaderID;
    EXEC dbo.SP_InsertApprovalLevelForRequest @PropertyID,
                                              @LocationID,
                                              @TransactionTypeID,
                                              @RequestHeaderID;


										

    EXEC sp_xml_removedocument @iDocID;
    IF @@TRANCOUNT > 0
        COMMIT TRAN;

END TRY
BEGIN CATCH

    RETURN CAST(ERROR_NUMBER() AS VARCHAR(10)) + ' - ' + ERROR_MESSAGE() + ' - On Line '
           + CAST(ERROR_LINE() AS VARCHAR(10));
    IF @@TRANCOUNT > 0
        ROLLBACK TRAN;
END CATCH;

GO

